import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../css/CentralizedGrievances.css'; // Import your CSS file for this component

const CentralizedGrievances = () => {
    const navigate = useNavigate();
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        state: '',
        complaintAgainst: '',
        disputedAmount: '',
        complaint: ''
    });

    const [complaintNumber, setComplaintNumber] = useState(null); // New state for complaint number
    const [error, setError] = useState(null); // New state for error handling

    const handleInputChange = (event) => {
        const { name, value } = event.target;
        setFormData({ ...formData, [name]: value });
    };

    
    const handleSubmit = async (event) => {
    event.preventDefault();

    const { name, email, phone, state, complaintAgainst, disputedAmount, complaint } = formData;

    try {
        const response = await axios.post("https://serve-d3eo.onrender.com/grievances", {
            name, email, phone, state, complaintAgainst, disputedAmount, complaint
        }, {
            headers: {
                "Content-Type": "application/json"
            }
        });

        if (response.status === 200) {
            const data = response.data;

            if (data.status === 422 || !data) {
                window.alert("Error: " + (data.message || "Invalid input"));
                console.log("Error:", data.message || "Invalid input");
            } else {
                setComplaintNumber(data.complaintNumber);
                setFormData({name: '',email: '',phone: '',state: '',complaintAgainst: '',disputedAmount: '',complaint: ''});
                window.alert("Successfully submitted");
                console.log("Successfully submitted");
                // navigate('/');
            }
        } else {
            window.alert("Unexpected response status: " + response.status);
            console.log("Unexpected response status:", response.status);
        }
    } catch (error) {
        // Handle error
        if (error.response) {
            // Server responded with a status other than 200 range
            window.alert("Submission failed: " + (error.response.data.message || error.message));
            console.error("Server error:", error.response.data);
        } else if (error.request) {
            // Request was made but no response received
            window.alert("Submission failed: No response from server");
            console.error("Network error:", error.request);
        } else {
            // Something happened in setting up the request
            window.alert("Submission failed: " + error.message);
            console.error("Error:", error.message);
        }
    }
};





    // const handleSubmit = async (event) => {
    //     event.preventDefault();
    //     const { name, email, phone, state, complaintAgainst, disputedAmount, complaint } = formData;
    //     const res = await fetch("/grievances", {
    //         method: "POST",
    //         headers: {
    //             "Content-Type": "application/json"
    //         },
    //         body: JSON.stringify({
    //             name, email, phone, state, complaintAgainst, disputedAmount, complaint
    //         })
    //     });
    //     const data = await res.json();
    //     if (data.status === 422 || !data) {
    //         window.alert("Error");
    //         console.log("error");
    //     } else {
    //         setComplaintNumber(data.complaintNumber);
    //         window.alert("Successfully submitted");
    //         console.log("Successfully submitted");
    //         // navigate('/');
    //     }
    // };

    const statesOfIndia = [
        'Andhra Pradesh', 'Arunachal Pradesh', 'Assam', 'Bihar', 'Chhattisgarh', 'Goa', 'Gujarat',
        'Haryana', 'Himachal Pradesh', 'Jharkhand', 'Karnataka', 'Kerala', 'Madhya Pradesh', 'Maharashtra',
        'Manipur', 'Meghalaya', 'Mizoram', 'Nagaland', 'Odisha', 'Punjab', 'Rajasthan', 'Sikkim',
        'Tamil Nadu', 'Telangana', 'Tripura', 'Uttar Pradesh', 'Uttarakhand', 'West Bengal'
    ];

    return (
        <div className="centralized-grievances-wrapper">
            <div className="centralized-grievances-container">
                <div className="grievance-form">
                    <h1>File your complaint</h1>
                    <form onSubmit={handleSubmit} method="POST">
                        <label htmlFor="name">Full Name:</label>
                        <input
                            type="text"
                            id="name"
                            name="name"
                            placeholder="Enter your Name"
                            value={formData.name}
                            onChange={handleInputChange}
                            required
                        />

                        <label htmlFor="email">Email:</label>
                        <input
                            type="email"
                            id="email"
                            name="email"
                            placeholder="Enter your Email"
                            value={formData.email}
                            onChange={handleInputChange}
                            required
                        />

                        <label htmlFor="phone">Mobile Number:</label>
                        <input
                            type="tel"
                            id="phone"
                            name="phone"
                            placeholder="Enter your Mobile"
                            value={formData.phone}
                            onChange={handleInputChange}
                            required
                        />

                        <label htmlFor="state">State:</label>
                        <select
                            id="state"
                            name="state"
                            placeholder="Select your State"
                            value={formData.state}
                            onChange={handleInputChange}
                            required
                        >
                            <option value="">Select State</option>
                            {statesOfIndia.map((state, index) => (
                                <option key={index} value={state}>{state}</option>
                            ))}
                        </select>

                        <label htmlFor="complaintAgainst">Complaint Against:</label>
                        <input
                            type="text"
                            id="complaintAgainst"
                            name="complaintAgainst"
                            placeholder="Complaint Against"
                            value={formData.complaintAgainst}
                            onChange={handleInputChange}
                            required
                        />

                        <label htmlFor="disputedAmount">Disputed Amount:</label>
                        <input
                            type="number"
                            id="disputedAmount"
                            name="disputedAmount"
                            placeholder="Enter disputed amount"
                            value={formData.disputedAmount}
                            onChange={handleInputChange}
                            required
                        />

                        <label htmlFor="complaint">Write Complaint:</label>
                        <textarea
                            id="complaint"
                            name="complaint"
                            rows="4"
                            placeholder="Enter the details"
                            value={formData.complaint}
                            onChange={handleInputChange}
                            required
                        ></textarea>

                        <button type="submit" name="submitGrievance" id="submitGrievance">Submit</button>
                    </form>

                    {complaintNumber && (
                        <div className="complaint-number">
                            <h2>Complaint Submitted Successfully</h2>
                            <p>Your complaint number is: <strong>{complaintNumber}</strong></p>
                            <p>kindly <strong>Note</strong> this complaint number to track complaint</p>
                        </div>
                    )}

                    {error && <p className="error">{error}</p>}

                </div>
            </div>

            <div className="sidebar">
                <div className="whats-new">
                    <h3>What's New</h3>
                    <div className="marquee-container">
                        <div className="marquee-content">
                            <ul>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!<span className="new-tag-in-content">New</span></li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!</li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!</li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Check out our new services and improvements regularly!</li>
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CentralizedGrievances;
