import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../css/CentralizedGrievances.css'; // Import your CSS file for this component
import axios from 'axios';

const TrackComplaint = () => {
    const navigate = useNavigate();
    const [complaintNumber, setComplaintNumber] = useState(''); // State for complaint number input
    const [complaintDetails, setComplaintDetails] = useState(null); // State for fetched complaint details
    const [error, setError] = useState(null); // State for error handling

    const handleInputChange = (event) => {
        setComplaintNumber(event.target.value);
    };

    const handleSubmit = async (event) => {
        event.preventDefault();
        try {
            // Make a GET request to fetch the data
            const res = await axios.get(`https://serve-d3eo.onrender.com/grievances/${complaintNumber}`);
            // Extract data from the response
            const data = res.data;
            // console.log("Received data:", data);
    
            // Check if there's an error or data is missing
            if (data.error || !data) {
                setError("Complaint number not found or error occurred.");
                setComplaintDetails(null);
            } else {
                setComplaintDetails(data);
                setError(null);
            }
        } catch (err) {
            // Handle any errors that occur during the request
            console.error("Error fetching data:", err);
            setError("An error occurred while fetching the complaint details.");
            setComplaintDetails(null);
        }
    };
    return (
        <div className="centralized-grievances-wrapper">
            <div className="centralized-grievances-container">
                <div className="grievance-form">
                    <h1>Track Your Complaint</h1>
                    <form onSubmit={handleSubmit} method="GET">
                        <label htmlFor="complaintNumber">Complaint Number:</label>
                        <input
                            type="text"
                            id="complaintNumber"
                            name="complaintNumber"
                            value={complaintNumber}
                            onChange={handleInputChange}
                            required
                        />

                        <button type="submit" name="trackComplaint" id="trackComplaint">Track</button>
                    </form>

                    {complaintDetails && (
    <div className="complaint-details">
        <h2>Complaint Details</h2>
        <table className="table">
            <thead>
                <tr>
                    <th>Field</th>
                    <th>Value</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Status</td>
                    <td>
                        <div 
                            className={`status-button ${
                                complaintDetails.status === 'initiated' ? 'status-initiated' :
                                complaintDetails.status === 'rejected' ? 'status-rejected' :
                                'status-other'
                            }`}
                        >
                            {complaintDetails.status}
                        </div>
                    </td>
                </tr>
                <tr>
                    <td>Full Name</td>
                    <td>{complaintDetails.name}</td>
                </tr>
                <tr>
                    <td>Email</td>
                    <td>{complaintDetails.email}</td>
                </tr>
                <tr>
                    <td>Mobile Number</td>
                    <td>{complaintDetails.phone}</td>
                </tr>
                <tr>
                    <td>State</td>
                    <td>{complaintDetails.state}</td>
                </tr>
                <tr>
                    <td>Complaint Against</td>
                    <td>{complaintDetails.complaintAgainst}</td>
                </tr>
                <tr>
                    <td>Disputed Amount</td>
                    <td>{complaintDetails.disputedAmount}</td>
                </tr>
                <tr>
                    <td>Complaint</td>
                    <td>{complaintDetails.complaint}</td>
                </tr>
            </tbody>
        </table>
    </div>
)}


                    {error && <p className="error">{error}</p>}

                </div>
            </div>

            <div className="sidebar">
                <div className="whats-new">
                    <h3>What's New</h3>
                    <div className="marquee-container">
                        <div className="marquee-content">
                            <ul>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!<span className="new-tag-in-content">New</span></li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!</li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Latest updates and features go here. Stay tuned for more updates and new features!</li>
                                <li>Check out our new services and improvements regularly!</li>
                                <li>Check out our new services and improvements regularly!</li>
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TrackComplaint;
